"""Export work/impl as a ProgramBench submission tree.

The harness extracts the submission into /workspace and runs ./compile.sh, which must
produce ./executable. The implementation is copied to DEST/impl (so it cannot collide
with bundled documentation) and DEST/compile.sh builds it there and installs a launcher.
"""
import os
import shutil

from common import wpath

WRAPPER = r"""#!/bin/sh
# Generated by probe_spec_code4_mini export: builds impl/ and installs ./executable.
set -e
cd "$(dirname "$0")"
ROOT="$(pwd -P)"
(cd impl && bash ./compile.sh)
test -f impl/executable
PY="$(command -v python3 || true)"
if [ -n "$PY" ] && [ "$(head -n 1 impl/executable)" = "#!/usr/bin/env python3" ]; then
    sed -i "1s|.*|#!$PY|" impl/executable
fi
rm -f executable
cat > executable <<EOF
#!/bin/bash
exec -a "\$0" "$ROOT/impl/executable" "\$@"
EOF
chmod 755 executable
"""


def export(dest):
    src = wpath("impl")
    if not os.path.isfile(os.path.join(src, "compile.sh")):
        raise SystemExit("work/impl/compile.sh not found")
    target = os.path.join(dest, "impl")
    if os.path.exists(target):
        shutil.rmtree(target)
    shutil.copytree(src, target, symlinks=True,
                    ignore=shutil.ignore_patterns("executable", "__pycache__", "*.pyc", ".git"))
    with open(os.path.join(dest, "compile.sh"), "w") as f:
        f.write(WRAPPER)
    os.chmod(os.path.join(dest, "compile.sh"), 0o755)
    gi = os.path.join(dest, ".gitignore")
    lines = open(gi).read().splitlines() if os.path.exists(gi) else []
    for pat in ("/executable", "/impl/executable", "__pycache__/", "*.pyc"):
        if pat not in lines:
            lines.append(pat)
    with open(gi, "w") as f:
        f.write("\n".join(lines) + "\n")
    return target
